WFI.Data.add("quest", {
  [79090] = { "Respingere gli invasori", "Porta il Warsong Outrider Mark a Felore Moonray, Priestess of the Moon, alla base del Moonwell, ad Ashenvale.", "Alcuni dei Warsong Outrider giacciono sconfitti, ma la battaglia infuria ancora...", nil, nil, 0xd7957bbe, 0xdef0139e, 0x793d0d29, nil, nil, "...mm" },
  [79091] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Dici che viene dalla biblioteca di Ironforge? ...Sono sicura che non ne sentiranno la mancanza.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, ti prego, portamele.", nil, nil, nil, 0x1400fbf0, 0xba293cb0, "mmm.." },
  [79092] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [79093] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [79097] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, nil, nil, nil, 0x1400fbf0, nil, "mmm.m" },
  [79098] = { "Ripulite la foresta!", "Porta il Silverwing Sentinel Charm a Kazragore, Far Seer, alla base del Bonfire, ad Ashenvale.", "Questo è morto, ma questa irritante alleanza continua a combattere... cos'è questo amuleto?", nil, nil, 0x47bae5fc, 0x072ac677, 0x0d462d55, nil, nil, "...mm" },
  [79192] = { "Pietre miliari", "Strappi il biglietto dall'asse e leggi la scrittura scarabocchiata.", "Il biglietto comincia così: \"La Mission ha detto che stavano entrambi facendo consegne per la New Plague. A me sembrano semplici incidenti da speziale. Trova il mio angolo tranquillo tra le montagne, fra The Barrens e Desolace, se vuoi un posto sicuro per parlare.\"", nil, "Senza dubbio qui si accampano sia avventurieri dell'entroterra sia mercenari. L'angolo di un biglietto che svolazza nella brezza attira la tua attenzione e allunghi la mano per prenderlo.", 0x9dd88a3c, 0x42f58b36, 0x18dc9772, nil, 0xf47f0ef5, "...m." },
  [79229] = { "Rapina sulla strada maestra", "Trova qualcuno a Desolace che sappia qualcosa dell'accampamento saccheggiato.", "L'accampamento davanti a te è una scena raccapricciante. A giudicare dai resti, le vittime erano due umani e un nano. I segni sulle ossa indicano un attacco feroce, ma le provviste saccheggiate ti dicono che non è stato un animale. Le ferite non corrispondono nemmeno alle armi dei centauri.\n\nForse un esperto razziatore di queste terre saprebbe cosa pensarne.", nil, nil, 0x3d1fe3af, 0xab3965fc, 0xaa70b186, nil, nil, "...mm" },
  [79362] = { nil, "Trova la Grant's Mace su uno degli scheletri del Raven Hill Cemetery, poi torna da Sirra Von'Indie, a Darkshire, per altre informazioni.", "Uno scudo lasciato dallo spettro di Grant Valor, padre della famiglia Valor ed eroe di Raven Hill.\n\nVisto che lo spirito di Grant combatte ancora i non morti, forse la sua questione in sospeso era uccidere il membro della Scourge che lo ferì nel Raven Hill Cemetery. Probabilmente è quello in cui è ancora conficcata la sua mazza.", nil, nil, nil, 0xe684af82, 0x80fde678, nil, nil, "m..mm" },
  [79363] = { nil, "Sconfiggi $N1 Defias Night Blade e $N2 Defias Enchanter all'Addle's Stead, poi torna da Sirra Von'Indi, a Darkshire, per altre informazioni.", "Una spada lasciata dallo spirito della guardia di Raven Hill, Silvia Valor, che visse la sua vita proteggendo i civili e le loro case.\n\nVisto che lo spirito di Silvia visita ancora le fattorie, forse la sua questione in sospeso era scacciare i Defias che si sono stabiliti all'Addle's Stead, a sud di Raven Hill.", nil, nil, nil, 0xef4e0f85, 0x1497337f, nil, nil, "m..mm" },
  [79482] = { "Dolcetti di Winter Veil rubati", "Trova l'investigatore di Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.", "Senti... non per rovinare la magia della stagione, ma a Smokywood Pastures servirebbe un po' d'aiuto, del tipo che voi avventurieri siete noti per dare.\n\nCi manca un'importante spedizione di dolcetti che doveva rifornirci per la stagione, e ora ci manca anche l'agente di Smokywood Pastures che abbiamo mandato a cercarla! Ti prego: la spedizione è stata segnalata l'ultima volta nelle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarla.\n\nVedi se sono entrambi là fuori, sani e salvi!", nil, nil, 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, nil, "...mm" },
  [79483] = { "Dolcetti di Winter Veil rubati", "Trova l'investigatore di Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.", "Senti... non per rovinare la magia della stagione, ma a Smokywood Pastures servirebbe un po' d'aiuto, del tipo che voi avventurieri siete noti per dare.\n\nCi manca un'importante spedizione di dolcetti che doveva rifornirci per la stagione, e ora ci manca anche l'agente di Smokywood Pastures che abbiamo mandato a cercarla! Ti prego: la spedizione è stata segnalata l'ultima volta nelle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarla.\n\nVedi se sono entrambi là fuori, sani e salvi!", nil, nil, 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, nil, "...mm" },
  [79492] = { nil, "Trova Metzen la renna. Usa gli appunti che ti sono stati dati come indizi per capire dove lo tengono prigioniero.\n\nQuando trovi Metzen, tieni con te la Pouch of Reindeer Dust così da poterlo cospargere con un po' di polvere; questo dovrebbe liberarlo dai suoi legami.\n\nUna volta liberato Metzen, riporta la Pouch of Reindeer Dust a Wulmort Jinglepocket, a Ironforge.", "È successo un disastro! Metzen the Reindeer è stato rapito!\n\nMetzen è una delle otto renne del Greatfather Winter, e di proprietà di Smokywood Pastures. Abbiamo ricevuto non una ma ben due lettere di riscatto da gruppi che sostengono di avere Metzen. Con la stagione delle feste in pieno svolgimento, qui siamo a corto di soldi! Ti prego, trova Metzen e riportacelo!\n\nControlla le lettere di riscatto in cerca di indizi, e cospargilo con questa polvere di renna: lo libererà da qualsiasi legame!\n\nTi prego, sbrigati!", nil, nil, nil, 0xcf081272, 0x3da2b74f, nil, nil, "m..mm" },
  [79637] = { "Un regalo che ticchetta", nil, nil, nil, nil, 0xd9f880a5, nil, nil, nil, nil, ".mmmm" },
})
